mapper.insert:
INSERT INTO pf.file_version(id,space_id,workspace_id,file_id,parent_version_id,asset_id,operation_id,sha256,size_bytes,actor_id)
SELECT version_id,space_id,workspace_id,file_id,parent_version_id,asset_id,operation_id,sha256,size_bytes,#{command.operation.actorId}
FROM pf.file_tree_restore_item WHERE operation_id=#{command.operation.id} AND kind='FILE'

mapper.sql:
FROM pf.artifact a JOIN pf.task t ON t.space_id=a.space_id AND t.id=a.task_id AND t.creator_id=#{actor.userId}
        JOIN pf.file_version v ON v.space_id=a.space_id AND v.id=a.version_id AND v.file_id=a.file_id AND v.workspace_id=a.workspace_id AND v.sha256=a.sha256 AND v.size_bytes=a.size_bytes
        JOIN pf.asset_object b ON b.space_id=a.space_id AND b.id=a.asset_id AND b.status='AVAILABLE' AND b.version_id=v.id AND b.sha256=v.sha256 AND b.size_bytes=v.size_bytes

mapper.select:
SELECT v.id,v.file_id,v.sha256,v.size_bytes,v.created_at,o.source_version_id
FROM pf.file_version v JOIN pf.asset_object a ON a.space_id=v.space_id AND a.id=v.asset_id AND a.status='AVAILABLE'
LEFT JOIN pf.file_version_origin o ON o.space_id=v.space_id AND o.version_id=v.id
WHERE v.space_id=#{space} AND v.file_id=#{file}
AND v.id<#{before}
ORDER BY v.id DESC LIMIT #{limit}
